// 2025-1-11 20:53
// 高维投影，彭罗斯镶嵌，准周期，拟周期
// https://www.shadertoy.com/view/XccXW8
// http://www.geom.uiuc.edu/apps/quasitiler/about.html


int N=7;  // N>1 // 维度  N==0 Auto


const int AC = 12;
float U[AC], V[AC],p[AC],tmp[AC],dotp[AC];
vec2 prop[AC];

vec2 fA, fB;
int fj,fi;

void aaa(int ind)
{
        for(int i = 0;i < N; i++)tmp[i]=0.;
        tmp[ind]=1.;
}

float dotN(float a[AC], float b[AC])
{
        float s = 0.;
        for(int i=0; i<N; i++)
        {
                s += a[i] * b[i];
        }
        return s;
}

vec2 proj(float p[AC])
{
        return vec2(dotN(p, U), dotN(p, V));
}

void init()
{
        float fN = float(N);
        float k = sqrt( 2. / fN ); // 单位长度因子
        for(int i = 0;i < N; i++)
        {
                U[i] = cos(radians(360./fN/2. * float(i))) * k;
                V[i] = sin(radians(360./fN/2. * float(i))) * k;
                //A[i]=0.;
                //B[i]=0.;
                aaa(i);
                prop[i]=proj(tmp);
        }
}





float tile(mat2 m, vec2 s)
{
        float e[AC];
        vec2 q = s * m ;


        for(int i=0; i<N; i++)
        {
                //e[i] = p[i] - (1.-A[i]-B[i])*round(dot(q,vec2(U[i],V[i])));//q.x * U[i] + q.y * V[i]);
                e[i] = p[i] - round(dot(q,vec2(U[i],V[i])));
        }
        e[fi] = p[fi];
        e[fj] = p[fj];


        vec2 f = .5 - abs(m * proj(e) -s);
        return max(0., min(f.x, f.y));
}


float faceAB()
{
        //mat2 m = inverse(mat2(proj(A), proj(B)));               
        //vec2 r = round(vec2(dotN(p,A), dotN(p,B)));

        mat2 m = inverse(mat2(prop[fj], prop[fi]));
        vec2 r = round(vec2(dotp[fj], dotp[fi]));

        vec2 s = vec2(.5, -.5);
        float d = tile(m, r+s.xx) + tile(m, r+s.xy) + tile(m, r+s.yx) + tile(m, r+s.yy);


        float lw = .04;  // line width
        float aa = 0.01;  // antialiasing width (depends on resolution and zoom)

        return d + smoothstep(lw-aa, lw+aa, //    0., 9.*5./iResolution.y, //
                   min(d / length(vec2(m[0].x, m[1].x)),
                       d / length(vec2(m[0].y, m[1].y))));
}



vec4 palette1(int i, int j){return vec4(1);}

vec4 palette2(int i, int j){return vec4(j*N+i, i*N+j,(i*j*3-i-j)%N/2,0)/float(N*N)*.5;}

vec4 palette3(int i, int j)
{
        vec4 a = .5 * (vec4((i*N+j)%2,(i^j*i)%3,(i*j)%2,0)*.9+.1)
               + .5 * vec4(j*N+i+j, i*N+j-i,(i*j*3)%N*N,0)/float(N*N)*.5;                                                 
        return a*a;
}

vec4 palette4(int i, int j)
{
        vec4 a = (vec4((i*N+j)%2,(i^j*i)%3,(i*j)%2,0)*.9+.1)
                 *vec4(j*N+i+j, i*N+j-i,(i*j*3)%N*N,0)/float(N*N);                                                      
        return a.yxzw;
}

vec4 palette5(int i, int j)
{// https://www.shadertoy.com/view/4djSRW
    vec2 p = vec2(i, j) + iMouse.xy   ;
	vec4 p4 = fract(vec4(p.xyxy) * vec4(.1031, .1030, .0973, .1099));
    p4 += dot(p4, p4.wzxy+33.33);
    return .5 * fract((p4.xxyz+p4.yzzw)*p4.zywx);

}

vec4 dim(vec2 u)
{
        init();
        vec4 c ;//= 0.;
        for(int i=0; i < N; i++)
        {
                p[i] = u.x * U[i] + u.y * V[i];
        }
        for(int i=0; i < N; i++)
        {
                aaa(i);
                dotp[i]=dotN(p, tmp);
        }


        for(int j =0; j< N-1;j++)
        {
                //A[j]=1.;
                fj=j;
                for(int i =j+1; i< N;i++)
                {
                        //B[i]=1.;
                        fi=i;
                        c += palette5(i,j) * faceAB(); 
                        //B[i]=0.;
                }      
                //A[j]=0.;
        }
        return c;
}




void mainImage( out vec4 O, vec2 U )
{

        vec2 R = iResolution.xy, 
             u = 5.*(U+U - R) / R.y + iTime;
        if(N<2)N = int(iTime) % AC+3;   ;// int(iMouse.x/R.x*float(Lth-3))% (Lth-3)+3; // iTime 对速度影响较大
        if(N>=AC)N=AC-1;
        O =  pow(dim(u),vec4(.25) );

}
